{
  "findings": [
    {
      "check_id": "CKV_AZURE_112",
      "title": "Key Vault key is not HSM-backed",
      "resource": "azurerm_key_vault_key.generated",
      "severity": "HIGH",
      "explanation": "The key uses the software-protected RSA key type, making its private key material less resistant to extraction and infrastructure compromise than an HSM-backed key."
    },
    {
      "check_id": "CKV_AZURE_40",
      "title": "Key Vault key has no expiration or rotation policy",
      "resource": "azurerm_key_vault_key.generated",
      "severity": "MEDIUM",
      "explanation": "The key has no configured lifecycle policy, so the same key version can remain active indefinitely and increase the impact of an undetected compromise."
    }
  ],
  "patched_code": "resource "azurerm_key_vault_key" "generated" {
  name         = "terragoat-generated-certificate-${var.environment}"
  key_vault_id = azurerm_key_vault.example.id
  key_type     = "RSA-HSM"
  key_size     = 2048
  key_opts = [
    "decrypt",
    "encrypt",
    "sign",
    "unwrapKey",
    "verify",
    "wrapKey",
  ]

  rotation_policy {
    automatic {
      time_after_creation = "P90D"
    }

    expire_after         = "P180D"
    notify_before_expiry = "P30D"
  }
}
",
  "fix_summary": "Changed the key to an HSM-backed RSA key and added an automatic 90-day rotation policy. Rotated key versions expire after 180 days with notification 30 days before expiry."
}
